def warn_inert_scalars(
    rewards_cfg: dict, compose_method: str, scale_rewards: str = "group"
) -> list[str]:
    """Return warnings for reward knobs that do nothing as configured.

    Under `advantage_weighted` every component is z-scored per prompt-group, so
    a component with no within-group variance contributes exactly 0 no matter
    what weight it carries. Under `naive_sum` with TRL's group std scaling the
    weight of a shaped term cancels in every group whose task reward is
    constant. Disabled rewards are skipped.
    """
    rc = rewards_cfg or {}
    warnings: list[str] = []

    shaped = [
        k
        for k in ("token_length", "non_termination")
        if (rc.get(k) or {}).get("enabled")
    ]
    if compose_method == "naive_sum" and scale_rewards == "group" and shaped:
        warnings.append(
            f"rewards {shaped} are summed into the task reward and TRL then divides "
            "each group's advantages by the group std (training.scale_rewards: group). "
            "In a group whose task reward is constant that std is weight * std(cost), "
            "so the weight cancels and the sweep measures presence, not dose (DIET, "
            "App. B). Set training.scale_rewards: none or batch for a dose-valid sweep."
        )

    # E3 is a binary flag, so it has zero within-group variance in any group
    # where every rollout terminates - and there it contributes exactly 0.
    # The penalty then goes silent precisely where behavior is already good,
    # which is not the shaped reward the expose specifies.
    if compose_method == "advantage_weighted" and (rc.get("non_termination") or {}).get(
        "enabled"
    ):
        warnings.append(
            "rewards.non_termination is binary, so advantage_weighted silences it in "
            "every prompt-group where all rollouts terminate (zero within-group "
            "variance contributes 0). Use compose_method: naive_sum for the lambda "
            "sweep, where weight is the penalty coefficient the expose defines."
        )

    return warnings


def _max_turns_error(env_cfg: dict, label: str):
    """Reject an explicit max_turns that resolve_max_turns would silently rewrite.

    resolve_max_turns coerces 0 and negatives to 1, so without this check a
    config stating max_turns: 0 trains and evals as a 1-turn episode while its
    frozen config records the 0 - the recorded cap and the executed cap disagree.
    """
    mt = env_cfg.get("max_turns")
    if mt is None:
        return None
    try:
        mt_i = int(mt)
    except (TypeError, ValueError):
        return f"{label}.max_turns={mt!r} is not an int"
    if mt_i < 1:
        return (
            f"{label}.max_turns={mt_i} must be >= 1: resolve_max_turns "
            f"would run 1 turn while the frozen config records {mt_i}"
        )
    return None


def _split_errors(
    splits, train_size: int = 500, default_n_episodes: int = 100
) -> list[str]:
    """Validate eval.agentic.splits.

    Split names key the report and the per-split episodes file, so a missing or
    duplicate name silently overwrites another split's results - checked here
    rather than discovered after a 2h eval.

    An explicit seed_offset is checked at both ends of its episode range
    [offset, offset + n_episodes): the low end against this seed's own training
    questions [0, train_size), the high end against SEED_BLOCK. Checking only
    the offset let a split near the block edge validate and still run its last
    episodes on the next seed's training questions.
    """
    if splits is None:
        return []
    if not isinstance(splits, list):
        return [f"eval.agentic.splits must be a list, got {type(splits).__name__}"]
    errors = []
    seen = set()
    for i, s in enumerate(splits):
        if not isinstance(s, dict):
            errors.append(f"eval.agentic.splits[{i}] must be a mapping, got {s!r}")
            continue
        unknown = set(s) - _KNOWN_EVAL_SPLIT_KEYS
        if unknown:
            errors.append(
                f"Unknown eval.agentic.splits[{i}] keys: {sorted(unknown)}. "
                f"Known: {sorted(_KNOWN_EVAL_SPLIT_KEYS)}"
            )
        name = s.get("name")
        if not name:
            errors.append(f"eval.agentic.splits[{i}] is missing `name`")
        elif name in seen:
            errors.append(f"Duplicate eval.agentic.splits name: {name!r}")
        else:
            seen.add(name)
        env_cfg = s.get("env_config")
        if isinstance(env_cfg, dict):
            unknown_ec = set(env_cfg) - _KNOWN_ENV_CONFIG_KEYS
            if unknown_ec:
                errors.append(
                    f"Unknown eval.agentic.splits[{i}].env_config keys: "
                    f"{sorted(unknown_ec)}. Known: {sorted(_KNOWN_ENV_CONFIG_KEYS)}"
                )
            mt_err = _max_turns_error(env_cfg, f"eval.agentic.splits[{i}].env_config")
            if mt_err:
                errors.append(mt_err)
        n_eps = s.get("n_episodes", default_n_episodes)
        try:
            n_eps = int(n_eps)
        except (TypeError, ValueError):
            errors.append(
                f"eval.agentic.splits[{i}].n_episodes={s.get('n_episodes')!r} is not an int"
            )
            n_eps = None
        offset = s.get("seed_offset")
        if offset is not None:
            try:
                off = int(offset)
            except (TypeError, ValueError):
                errors.append(
                    f"eval.agentic.splits[{i}].seed_offset={offset!r} is not an int"
                )
            else:
                if off < 0:
                    errors.append(
                        f"eval.agentic.splits[{i}].seed_offset={off} is negative"
                    )
                elif off < train_size:
                    errors.append(
                        f"eval.agentic.splits[{i}].seed_offset={off} lands inside "
                        f"this seed's training questions [0, {train_size}): a "
                        f"held-out split would replay trained questions"
                    )
                if n_eps is not None and off >= 0 and off + n_eps > SEED_BLOCK:
                    errors.append(
                        f"eval.agentic.splits[{i}].seed_offset={off} + "
                        f"n_episodes={n_eps} crosses SEED_BLOCK={SEED_BLOCK}: the "
                        f"last episodes would run on the next seed's training "
                        f"questions"
                    )
    return errors


def _get_nested(d: dict, key: str):
    parts = key.split(".")
    cur = d
    for p in parts:
        if not isinstance(cur, dict) or p not in cur:
            return None
        cur = cur[p]
    return cur


def validate_config(config: dict) -> None:
    """Validate config in-place-free: never mutates the input dict.

    A previous version coerced int fields to floats via _set_nested, which
    leaked floats (e.g. max_steps: 500.0) into the frozen runs/<exp>/config.yaml.
    Range checks now operate on a local float copy only.
    """
    errors = []
    try:
        if resolve_checkpoint_steps(config) and not _get_nested(
            config, "eval.reference_report"
        ):
            errors.append("checkpoint_schedule: thirds requires eval.reference_report")
    except ValueError as exc:
        errors.append(str(exc))

    for key, label in _REQUIRED_KEYS.items():
        if _get_nested(config, key) is None:
            errors.append(f"Missing required field: {label}")

    # Agentic-only: every config runs against an OpenEnv environment.
    mode = (config.get("training") or {}).get("mode", "agentic")
    if mode != "agentic":
        errors.append(f"training.mode={mode!r}: only 'agentic' is supported")
    if _get_nested(config, "training.env") is None:
        errors.append(
            "Missing required field: training.env (str) - OpenEnv environment id"
        )

    for key, (lo, hi) in _NUMERIC_COERCIONS.items():
        val = _get_nested(config, key)
        if val is None:
            continue
        try:
            fval = float(val)
        except (TypeError, ValueError):
            errors.append(f"Field {key}={val!r} is not numeric")
            continue
        if not (lo <= fval <= hi):
            errors.append(f"Field {key}={val} out of range [{lo}, {hi}]")

    slug = _get_nested(config, "model.slug")
    if slug is not None:
        from training.registry import MODEL_REGISTRY

        if slug not in MODEL_REGISTRY:
            errors.append(
                f"model.slug={slug!r} not in registry. Available: {list(MODEL_REGISTRY)}"
            )
        else:
            # Cross-check lora_r against the registry's max for this model;
            # _NUMERIC_COERCIONS upper bound (256) is permissive across all models.
            lora_r = _get_nested(config, "model.lora_r")
            max_rank = MODEL_REGISTRY[slug].get("max_lora_rank")
            if lora_r is not None and max_rank is not None:
                try:
                    if int(lora_r) > int(max_rank):
                        errors.append(
                            f"model.lora_r={lora_r} exceeds registry max_lora_rank={max_rank} for slug={slug!r}"
                        )
                except (TypeError, ValueError):
                    pass

    compose = _get_nested(config, "rewards.compose_method")
    if compose is not None and compose not in ("advantage_weighted", "naive_sum"):
        errors.append(
            f"rewards.compose_method={compose!r} must be 'advantage_weighted' or 'naive_sum'"
        )

    rewards = config.get("rewards") or {}
    unknown_rewards = set(rewards.keys()) - _KNOWN_REWARD_KEYS
    if unknown_rewards:
        errors.append(
            f"Unknown rewards keys: {sorted(unknown_rewards)}. Known: {sorted(_KNOWN_REWARD_KEYS)}"
        )

    for reward_name in _KNOWN_REWARD_SUBKEYS:  # excludes compose_method (a string)
        val = rewards.get(reward_name)
        if val is not None and not isinstance(val, dict):
            errors.append(
                f"rewards.{reward_name} must be a mapping (e.g. {{enabled: false}}), "
                f"got {type(val).__name__}: {val!r}"
            )

    for reward_name, allowed in _KNOWN_REWARD_SUBKEYS.items():
        sub = rewards.get(reward_name)
        if not isinstance(sub, dict):
            continue
        unknown_sub = set(sub.keys()) - allowed
        if unknown_sub:
            errors.append(
                f"Unknown sub-keys under rewards.{reward_name}: {sorted(unknown_sub)}. "
                f"Allowed: {sorted(allowed)}"
            )

    model = config.get("model")
    if isinstance(model, dict):
        unknown_model = set(model) - _KNOWN_MODEL_KEYS
        if unknown_model:
            errors.append(
                f"Unknown model keys: {sorted(unknown_model)}. "
                f"Known: {sorted(_KNOWN_MODEL_KEYS)}"
            )

    training = config.get("training")
    if isinstance(training, dict):
        unknown_tr = set(training) - _KNOWN_TRAINING_KEYS
        if unknown_tr:
            errors.append(
                f"Unknown training keys: {sorted(unknown_tr)}. "
                f"Known: {sorted(_KNOWN_TRAINING_KEYS)}"
            )
        env_server = training.get("env_server")
        if isinstance(env_server, dict):
            unknown_es = set(env_server) - _KNOWN_ENV_SERVER_KEYS
            if unknown_es:
                errors.append(
                    f"Unknown training.env_server keys: {sorted(unknown_es)}. "
                    f"Known: {sorted(_KNOWN_ENV_SERVER_KEYS)}"
                )
        scale = training.get("scale_rewards")
        if scale is not None and scale not in _KNOWN_SCALE_REWARDS:
            raise ValueError(
                f"Unknown training.scale_rewards: {scale!r}. "
                f"Known: {sorted(_KNOWN_SCALE_REWARDS)}"
            )
        is_mode = training.get("vllm_importance_sampling_mode")
        if is_mode is not None and is_mode not in _KNOWN_VLLM_IS_MODES:
            errors.append(
                f"Unknown training.vllm_importance_sampling_mode: {is_mode!r}. "
                f"Known: {sorted(_KNOWN_VLLM_IS_MODES)}"
            )

    env_config = (config.get("training") or {}).get("env_config")
    if isinstance(env_config, dict):
        unknown_ec = set(env_config) - _KNOWN_ENV_CONFIG_KEYS
        if unknown_ec:
            errors.append(
                f"Unknown training.env_config keys: {sorted(unknown_ec)}. "
                f"Known: {sorted(_KNOWN_ENV_CONFIG_KEYS)}"
            )
        mt_err = _max_turns_error(env_config, "training.env_config")
        if mt_err:
            errors.append(mt_err)

    eval_cfg = config.get("eval")
    if isinstance(eval_cfg, dict):
        unknown_eval = set(eval_cfg) - _KNOWN_EVAL_KEYS
        if unknown_eval:
            errors.append(
                f"Unknown eval keys: {sorted(unknown_eval)}. Known: {sorted(_KNOWN_EVAL_KEYS)}"
            )
        agentic = eval_cfg.get("agentic")
        if isinstance(agentic, dict):
            unknown_ag = set(agentic) - _KNOWN_EVAL_AGENTIC_KEYS
            if unknown_ag:
                errors.append(
                    f"Unknown eval.agentic keys: {sorted(unknown_ag)}. "
                    f"Known: {sorted(_KNOWN_EVAL_AGENTIC_KEYS)}"
                )
            # Mirror the resolutions the pipeline itself applies: training
            # questions occupy [0, env_config.size) with train.py's default of
            # 500, and a split without n_episodes falls back to
            # eval.agentic.n_episodes (agentic_eval defaults it to 100).
            size_val = (
                env_config.get("size", 500) if isinstance(env_config, dict) else 500
            )
            try:
                train_size = int(size_val)
            except (TypeError, ValueError):
                train_size = 500
            try:
                default_n = int(agentic.get("n_episodes", 100))
            except (TypeError, ValueError):
                default_n = 100
            errors.extend(
                _split_errors(
                    agentic.get("splits"),
                    train_size=train_size,
                    default_n_episodes=default_n,
                )
            )

    unknown_top = set(config.keys()) - _KNOWN_TOP_LEVEL_KEYS
    if unknown_top:
        errors.append(
            f"Unknown top-level keys: {sorted(unknown_top)}. Known: {sorted(_KNOWN_TOP_LEVEL_KEYS)}"
        )

    if errors:
        msg = "Config validation failed:\n" + "\n".join(f" - {e}" for e in errors)
        raise ValueError(msg)

