    cfg = _agentic_base()
    cfg["training"]["max_prompt_lenght"] = 6144  # the real typo shape
    with pytest.raises(ValueError, match="training keys"):
        validate_config(cfg)


def test_rejects_training_key_that_is_read_nowhere():
