    # batch_size / micro_batch_size, and dataset size comes from env_config.size.
    for dead in ("gradient_accumulation_steps", "dataset_size_limit"):
        cfg = _agentic_base()
        cfg["training"][dead] = 8
        with pytest.raises(ValueError, match="training keys"):
            validate_config(cfg)


