    cfg = _agentic_base()
    cfg["training"].update(
        max_prompt_length=1024,
        max_steps=300,
        save_steps=100,
        n_rollouts=8,
        batch_size=1,
        micro_batch_size=2,
        learning_rate=5e-6,
        kl_beta=0.001,
        temperature=1.0,
