    def record_loss(self, inputs, loss, per_token_logps, settings: dict) -> None:
        if self._loss_shards >= self.max_loss_shards:
            return
        selected = {
            key: value
            for key, value in inputs.items()
            if key
            in {
                "completion_ids",
                "completion_mask",
                "tool_mask",
